script:
// Variables hold stages (or filters, or anything) you reuse. aggregate() takes the stages as separate arguments too.
var GROUP = { $group: { _id: "$external_id", count: { $sum: 1 } } }
var KEEP_IDS = { $group: { _id: "$external_id", count: { $sum: 1 }, docs: { $push: "$_id" } } }
var DUPLICATES = { $match: { count: { $gt: 1 } } }
var BIGGEST_FIRST = { $sort: { count: -1, _id: 1 } }

// which external_ids appear more than once?
db.orders.aggregate(GROUP, DUPLICATES, BIGGEST_FIRST)

// and which documents are they?
db.orders.aggregate(KEEP_IDS, DUPLICATES, BIGGEST_FIRST)

